import { Student, RuleItem, ColumnRow, AttendanceRecord, EmulationLog, DutyDayConfig } from '../data/types';
import { INITIAL_STUDENTS, INITIAL_RULES, INITIAL_SEATING_LAYOUT, INITIAL_DUTY_CONFIG } from '../data/initialData';

const STORAGE_KEYS = {
  STUDENTS: '11a7_students',
  RULES: '11a7_rules',
  SEATING: '11a7_seating',
  ATTENDANCE: '11a7_attendance',
  EMULATION_LOGS: '11a7_emulation_logs',
  DUTY_CONFIG: '11a7_duty_config',
};

export const loadStudents = (): Student[] => {
  if (typeof window === 'undefined') return INITIAL_STUDENTS;
  try {
    const data = localStorage.getItem(STORAGE_KEYS.STUDENTS);
    return data ? JSON.parse(data) : INITIAL_STUDENTS;
  } catch (e) {
    console.error('Error loading students', e);
    return INITIAL_STUDENTS;
  }
};

export const saveStudents = (students: Student[]) => {
  if (typeof window === 'undefined') return;
  localStorage.setItem(STORAGE_KEYS.STUDENTS, JSON.stringify(students));
};

