'use client';

import React, { useState, useEffect } from 'react';
import { Navbar } from '../components/Navbar';
import { SeatingChart } from '../components/SeatingChart/SeatingChart';
import { AttendanceManager } from '../components/Attendance/AttendanceManager';
import { EmulationManager } from '../components/Emulation/EmulationManager';
import { RuleLookup } from '../components/RuleLookup/RuleLookup';
import { DutyScheduleManager } from '../components/DutySchedule/DutyScheduleManager';

import { Student, RuleItem, ColumnRow, AttendanceRecord, EmulationLog, DutyDayConfig } from '../data/types';
import { INITIAL_STUDENTS, INITIAL_RULES, INITIAL_SEATING_LAYOUT, INITIAL_DUTY_CONFIG, INITIAL_DUTY_TASKS } from '../data/initialData';
import {
  loadStudents, saveStudents,
  loadRules, saveRules,
  loadSeating, saveSeating,
  loadAttendance, saveAttendance,
  loadEmulationLogs, saveEmulationLogs,
  loadDutyConfig, saveDutyConfig,
  resetAllData
} from '../utils/storage';

export default function Home() {
  const [activeTab, setActiveTab] = useState('seating');
  const [isLoaded, setIsLoaded] = useState(false);

  // States
  const [students, setStudents] = useState<Student[]>(INITIAL_STUDENTS);
  const [rules, setRules] = useState<RuleItem[]>(INITIAL_RULES);
  const [seatingLayout, setSeatingLayout] = useState<ColumnRow[]>(INITIAL_SEATING_LAYOUT);
  const [attendanceRecords, setAttendanceRecords] = useState<AttendanceRecord[]>([]);
  const [emulationLogs, setEmulationLogs] = useState<EmulationLog[]>([]);
  const [dutyConfig, setDutyConfig] = useState<DutyDayConfig[]>(INITIAL_DUTY_CONFIG);

  // Hydrate from LocalStorage
  useEffect(() => {
    setStudents(loadStudents());
    setRules(loadRules());
    setSeatingLayout(loadSeating());
    setAttendanceRecords(loadAttendance());
    setEmulationLogs(loadEmulationLogs());
    setDutyConfig(loadDutyConfig());
    setIsLoaded(true);
  }, []);

  // Sync state changes to storage
  const handleUpdateSeating = (newLayout: ColumnRow[]) => {
    setSeatingLayout(newLayout);
    saveSeating(newLayout);
  };

  const handleSaveAttendance = (newRecord: AttendanceRecord) => {
    const updated = [
      ...attendanceRecords.filter(r => r.date !== newRecord.date),
      newRecord,
    ];
    setAttendanceRecords(updated);
    saveAttendance(updated);
  };

  const handleAddEmulationLog = (logData: Omit<EmulationLog, 'id'>) => {
    const newLog: EmulationLog = {
      ...logData,
      id: `log-${Date.now()}-${Math.random().toString(36).substr(2, 4)}`,
    };
    const updated = [newLog, ...emulationLogs];
    setEmulationLogs(updated);
    saveEmulationLogs(updated);
  };

  const handleDeleteEmulationLog = (id: string) => {
    const updated = emulationLogs.filter(l => l.id !== id);
    setEmulationLogs(updated);
    saveEmulationLogs(updated);
  };

  const handleUpdateRules = (newRules: RuleItem[]) => {
    setRules(newRules);
    saveRules(newRules);
  };

  const handleUpdateDutyConfig = (newConfig: DutyDayConfig[]) => {
    setDutyConfig(newConfig);
    saveDutyConfig(newConfig);
  };

  const handleResetData = () => {
    resetAllData();
    setStudents(INITIAL_STUDENTS);
    setRules(INITIAL_RULES);
    setSeatingLayout(INITIAL_SEATING_LAYOUT);
    setAttendanceRecords([]);
    setEmulationLogs([]);
    setDutyConfig(INITIAL_DUTY_CONFIG);
  };

  if (!isLoaded) {
    return (
      <div className="min-h-screen bg-slate-100 flex items-center justify-center">
        <div className="text-center space-y-3">
          <div className="w-12 h-12 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mx-auto"></div>
          <p className="text-xs font-bold text-slate-600">Đang tải dữ liệu Lớp 11A7...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col bg-slate-100/80">
      {/* Navigation Bar */}
      <Navbar
        activeTab={activeTab}
        setActiveTab={setActiveTab}
        onResetData={handleResetData}
        totalStudents={students.length}
      />

      {/* Main Content Area */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6">
        {activeTab === 'seating' && (
          <SeatingChart
            students={students}
            layout={seatingLayout}
            onUpdateLayout={handleUpdateSeating}
          />
        )}

        {activeTab === 'attendance' && (
          <AttendanceManager
            students={students}
            attendanceRecords={attendanceRecords}
            onSaveRecord={handleSaveAttendance}
          />
        )}

        {activeTab === 'emulation' && (
          <EmulationManager
            students={students}
            rules={rules}
            logs={emulationLogs}
            onAddLog={handleAddEmulationLog}
            onDeleteLog={handleDeleteEmulationLog}
          />
        )}

        {activeTab === 'rules' && (
          <RuleLookup
            rules={rules}
            onUpdateRules={handleUpdateRules}
          />
        )}

        {activeTab === 'duty' && (
          <DutyScheduleManager
            students={students}
            dutyConfig={dutyConfig}
            tasks={INITIAL_DUTY_TASKS}
            onUpdateDutyConfig={handleUpdateDutyConfig}
          />
        )}
      </main>

      {/* Footer */}
      <footer className="bg-white border-t border-slate-200 py-4 text-center text-xs text-slate-500">
        <div className="max-w-7xl mx-auto px-4">
          <p className="font-semibold">Bản quyền © 2026 - Lớp 11A7 • Hệ Thống Quản Lý Lớp Học Thông Minh</p>
        </div>
      </footer>
    </div>
  );
}
