'use client';

import React from 'react';
import { LayoutGrid, ClipboardCheck, Award, FileSearch, Calendar, Users, RefreshCw } from 'lucide-react';

interface NavbarProps {
  activeTab: string;
  setActiveTab: (tab: string) => void;
  onResetData: () => void;
  totalStudents: number;
}

export const Navbar: React.FC<NavbarProps> = ({
  activeTab,
  setActiveTab,
  onResetData,
  totalStudents,
}) => {
  const tabs = [
    { id: 'seating', label: 'Sơ Đồ Chỗ Ngồi', icon: LayoutGrid, desc: 'Bàn 3 chỗ & Kéo thả' },
    { id: 'attendance', label: 'Điểm Danh', icon: ClipboardCheck, desc: 'Tick chọn theo ngày' },
    { id: 'emulation', label: 'Điểm Thi Đua', icon: Award, desc: 'Bảng xếp hạng & Cộng trừ điểm' },
    { id: 'rules', label: 'Tra Cứu Lỗi', icon: FileSearch, desc: 'Quy định & Upload Docx' },
    { id: 'duty', label: 'Lịch Trực Nhật', icon: Calendar, desc: 'Học chính & Học nghề' },
  ];

  return (
    <header className="bg-white border-b border-slate-200 sticky top-0 z-30 shadow-sm">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16">
          {/* Brand Logo & Title */}
          <div className="flex items-center space-x-3">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-blue-600 to-indigo-600 flex items-center justify-center text-white font-extrabold text-xl shadow-md">
              11A7
            </div>
            <div>
              <h1 className="text-lg font-bold text-slate-800 leading-tight">
                QUẢN LÝ LỚP 11A7
              </h1>
              <p className="text-xs text-slate-500 flex items-center gap-1.5">
                <Users className="w-3.5 h-3.5 text-blue-500" /> Sĩ số: <span className="font-semibold text-slate-700">{totalStudents}</span> học sinh
              </p>
            </div>
          </div>

          {/* Navigation Tabs */}
          <nav className="hidden md:flex space-x-1">
            {tabs.map((tab) => {
              const Icon = tab.icon;
              const isActive = activeTab === tab.id;
              return (
                <button
                  key={tab.id}
                  onClick={() => setActiveTab(tab.id)}
                  className={`flex items-center space-x-2 px-3.5 py-2 rounded-lg text-sm font-medium transition-all ${
                    isActive
                      ? 'bg-blue-50 text-blue-600 font-semibold shadow-sm border border-blue-200/60'
                      : 'text-slate-600 hover:text-slate-900 hover:bg-slate-50'
                  }`}
                >
                  <Icon className={`w-4 h-4 ${isActive ? 'text-blue-600' : 'text-slate-400'}`} />
                  <span>{tab.label}</span>
                </button>
              );
            })}
          </nav>

          {/* Action button: Reset data */}
          <div className="flex items-center space-x-2">
            <button
              onClick={() => {
                if (confirm('Bạn có chắc chắn muốn khôi phục dữ liệu ban đầu về trạng thái mặc định của Lớp 11A7?')) {
                  onResetData();
                }
              }}
              title="Khôi phục dữ liệu ban đầu"
              className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors flex items-center gap-1 text-xs font-medium border border-transparent hover:border-red-200"
            >
              <RefreshCw className="w-4 h-4" />
              <span className="hidden sm:inline">Khôi phục mặc định</span>
            </button>
          </div>
        </div>

        {/* Mobile Navigation Tabs */}
        <div className="md:hidden flex overflow-x-auto py-2 space-x-1 border-t border-slate-100 no-scrollbar">
          {tabs.map((tab) => {
            const Icon = tab.icon;
            const isActive = activeTab === tab.id;
            return (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`flex items-center space-x-1.5 px-3 py-1.5 rounded-lg text-xs font-medium whitespace-nowrap ${
                  isActive
                    ? 'bg-blue-600 text-white shadow-sm'
                    : 'bg-slate-100 text-slate-600'
                }`}
              >
                <Icon className="w-3.5 h-3.5" />
                <span>{tab.label}</span>
              </button>
            );
          })}
        </div>
      </div>
    </header>
  );
};
